// Leave Request Approval Bot: core logic (ported from main.py)
const CFG = {
 "year": 2026,
 "holidays": [
  "2026-10-01",
  "2026-12-25",
  "2026-12-26"
 ],
 "blackouts": [
  {
   "name": "Month-end close",
   "from": "2026-10-28",
   "to": "2026-10-31",
   "teams": [
    "Finance"
   ]
  }
 ],
 "min_on_duty": {
  "Support": 2,
  "Finance": 1
 },
 "staff": {
  "Amaka": {
   "team": "Support",
   "balance": 12
  },
  "Bayo": {
   "team": "Support",
   "balance": 3
  },
  "Chinedu": {
   "team": "Support",
   "balance": 10
  },
  "Dupe": {
   "team": "Finance",
   "balance": 15
  },
  "Efe": {
   "team": "Finance",
   "balance": 8
  }
 },
 "already_approved": {
  "Chinedu": [
   "2026-10-21",
   "2026-10-22"
  ]
 }
};
// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
const parse = t => { const m = t.toLowerCase().match(/(\d{1,2})(?:st|nd|rd|th)?\s*(?:([a-z]{3})[a-z]*)?\s*(?:to|-|until|till)\s*(\d{1,2})(?:st|nd|rd|th)?\s*([a-z]{3})[a-z]*/);
  if (!m) return null; const m1 = MONTHS[m[2]] ? m[2] : m[4];
  return [new Date(Date.UTC(CFG.year, MONTHS[m1] - 1, +m[1])), new Date(Date.UTC(CFG.year, MONTHS[m[4]] - 1, +m[3]))]; };
const iso = d => d.toISOString().slice(0, 10);
const approved = JSON.parse(JSON.stringify(CFG.already_approved)), out = [];
for (const r of input) {
  const emp = r.Employee || r.employee, text = r.Request || r.text, staff = CFG.staff[emp];
  const span = parse(text); let decision, reason;
  if (!staff) { decision = 'CLARIFY'; reason = 'employee not found'; }
  else if (!span) { decision = 'CLARIFY'; reason = "couldn't read the dates; please use e.g. '20 Oct to 24 Oct'"; }
  else {
    const days = []; for (let d = new Date(span[0]); d <= span[1]; d.setUTCDate(d.getUTCDate() + 1)) { const w = d.getUTCDay(); if (w && w !== 6 && !CFG.holidays.includes(iso(d))) days.push(iso(d)); }
    const black = CFG.blackouts.find(b => b.teams.includes(staff.team) && days.some(d => d >= b.from && d <= b.to));
    const team = Object.keys(CFG.staff).filter(n => CFG.staff[n].team === staff.team);
    const thin = days.find(d => team.length - 1 - team.filter(n => n !== emp && (approved[n] || []).includes(d)).length < CFG.min_on_duty[staff.team]);
    if (days.length > staff.balance) { decision = 'DECLINE'; reason = `needs ${days.length} days but balance is ${staff.balance}`; }
    else if (black) { decision = 'DECLINE'; reason = 'overlaps blackout: ' + black.name; }
    else if (thin) { decision = 'ROUTE TO MANAGER'; reason = `${staff.team} would be below minimum cover on ${thin}`; }
    else { decision = 'APPROVED'; reason = `${days.length} working days; balance after: ${staff.balance - days.length}`;
      staff.balance -= days.length; (approved[emp] = approved[emp] || []).push(...days); }
  }
  out.push({ route: decision, employee: emp, request: text, decision, reason });
}
return out.map(json => ({ json }));
